SELECT ca.ca_country AS country, td.t_hour AS hour_of_day, COUNT(DISTINCT c.c_customer_sk) AS distinct_customers, SUM(ws.ws_net_profit) AS total_sales_net_profit, COALESCE(SUM(wr.wr_net_loss), 0) AS total_return_net_loss, SUM(ws.ws_quantity) AS total_quantity_sold, COALESCE(SUM(wr.wr_return_quantity), 0) AS total_quantity_returned, SUM(ws.ws_ext_discount_amt) / NULLIF(SUM(ws.ws_quantity), 0) AS avg_discount_per_item, (SUM(ws.ws_net_profit) - COALESCE(SUM(wr.wr_net_loss), 0)) AS net_profit_after_returns, CASE WHEN SUM(ws.ws_quantity) > 0 THEN COALESCE(SUM(wr.wr_return_quantity), 0) / SUM(ws.ws_quantity) ELSE 0 END AS return_rate FROM web_sales ws JOIN time_dim td ON ws.ws_sold_time_sk = td.t_time_sk JOIN customer c ON ws.ws_bill_customer_sk = c.c_customer_sk JOIN customer_address ca ON ws.ws_bill_addr_sk = ca.ca_address_sk JOIN web_page wp ON ws.ws_web_page_sk = wp.wp_web_page_sk LEFT JOIN web_returns wr ON ws.ws_order_number = wr.wr_order_number AND ws.ws_item_sk = wr.wr_item_sk WHERE c.c_birth_year BETWEEN 1950 AND 1970 AND c.c_preferred_cust_flag = 'Y' AND td.t_hour BETWEEN 9 AND 17 AND ca.ca_gmt_offset BETWEEN -5 AND 5 AND wp.wp_type = 'product' GROUP BY ca.ca_country, td.t_hour ORDER BY total_sales_net_profit DESC LIMIT 100
